class Solution {
  public int findMinimumTime(List<Integer> strength, int k) {
    int n = strength.size();
    int[] dp = new int[1 << n];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
      if (dp[mask] == Integer.MAX_VALUE) continue;
      int x = 1 + k * Integer.bitCount(mask);
      for (int i = 0; i < n; i++) {
        if ((mask >> i & 1) != 0) continue;
        int t = dp[mask] + (strength.get(i) + x - 1) / x;
        if (t < dp[mask | 1 << i]) dp[mask | 1 << i] = t;
      }
    }
    return dp[(1 << n) - 1];
  }
}
